"""What each module checks, in plain words, and how far its accuracy is known. Shown on every module card and (Phase 5)
in the PDF report, so a reader can tell a measured detector from a reasoned heuristic at a glance."""

ABOUT: dict[str, tuple[str, str, str]] = {
    # modality: (what it checks, "measured" | "heuristic", how far its accuracy is known)
    "image": (
        "Whether the picture was generated by AI. Two detectors score the whole image and their outputs are averaged: "
        "UnivFD (CLIP image features plus a trained linear layer, strong on GAN faces) and a Swin-V2 classifier "
        "(strong on 2025 diffusion generators). ELA, noise, face landmarks and EXIF are supporting evidence and do "
        "not change the score.",
        "measured",
        "77% correct on 180 held-out images (StyleGAN faces; 2023 diffusion images; 2025 generators such as Midjourney 7, "
        "GPT-image and Flux; real photos), catching 63% of fakes and wrongly flagging 9% of real photos. "
        "Misses about half of diffusion fakes and flags some real faces. Not built for face swaps. See evaluation/IMAGE_RESULTS.md.",
    ),
    "audio": (
        "Whether the voice sounds synthetic (text-to-speech or voice cloning). VoxShield's two wav2vec2 anti-spoofing "
        "detectors score 6-second windows; the score is their median.",
        "measured",
        "VoxShield benchmark, English and Hindi: on clean audio no real voice was called fake and most synthetic voices "
        "were caught; over phone codecs most neural voices were missed. See evaluation/VOICE_RESULTS.md.",
    ),
    "video_frames": (
        "Whether individual frames look AI-generated. The image detector (UnivFD) scores 16 evenly spaced whole frames; "
        "the score is the median frame.",
        "measured",
        "Measured on still images only (77% on 180 held-out images). Not yet measured on video, where compression can "
        "shift scores, and not built for face swaps, which keep most of each frame real.",
    ),
    "lipsync": (
        "Audio-visual sync consistency: whether the mouth opens and closes as the audio gets louder and quieter, and "
        "whether the two are in step. Loudness only, not phoneme-level analysis.",
        "heuristic",
        "Cut-offs set by reasoning, not yet measured on labelled videos. It can add weight to the verdict but never "
        "decides it alone.",
    ),
    "video_temporal": (
        "Frame-to-frame consistency: whether the rigid parts of the face (nose, forehead, cheekbones) keep their shape "
        "between frames once head motion is removed. Face-swap blending often makes them wobble for a frame or two.",
        "heuristic",
        "Cut-offs set by reasoning, not yet measured on labelled videos. It can add weight to the verdict but never "
        "decides it alone.",
    ),
}


def describe(module):
    """The module with its plain-language description filled in, unless it already has one."""
    if module.checks or module.modality not in ABOUT:
        return module
    checks, basis, note = ABOUT[module.modality]
    return module.model_copy(update={"checks": checks, "basis": basis, "basis_note": note})
